const { retry } = require('./retry');

describe('retry', () => {
  beforeEach(() => {
    jest.useFakeTimers();
  });

  afterEach(() => {
    jest.useRealTimers();
  });

  test('succeeds on the third attempt after two failures', async () => {
    const fn = jest
      .fn()
      .mockRejectedValueOnce(new Error('fail 1'))
      .mockRejectedValueOnce(new Error('fail 2'))
      .mockResolvedValue('ok');

    const promise = retry(fn, { retries: 3, delayMs: 1000 });
    await jest.advanceTimersByTimeAsync(2000);

    await expect(promise).resolves.toBe('ok');
    expect(fn).toHaveBeenCalledTimes(3);
  });

  test('does not retry until delayMs has elapsed', async () => {
    const fn = jest.fn().mockRejectedValueOnce(new Error('fail')).mockResolvedValue('ok');

    const promise = retry(fn, { retries: 1, delayMs: 1000 });
    await jest.advanceTimersByTimeAsync(999);
    expect(fn).toHaveBeenCalledTimes(1);

    await jest.advanceTimersByTimeAsync(1);
    expect(fn).toHaveBeenCalledTimes(2);
    await expect(promise).resolves.toBe('ok');
  });

  test('rejects with the last error after exhausting retries', async () => {
    const fn = jest.fn().mockImplementation(async (attempt) => {
      throw new Error(`fail ${attempt}`);
    });

    const assertion = expect(retry(fn, { retries: 2, delayMs: 500 })).rejects.toThrow('fail 2');
    await jest.advanceTimersByTimeAsync(1000);

    await assertion;
    expect(fn).toHaveBeenCalledTimes(3);
  });
});
